-- ecommerce_medium_enhanced.sql
-- Enhanced medium dataset: payments, reviews, inventory, analytics, realistic text

DROP SCHEMA public CASCADE;
CREATE SCHEMA public;
SET search_path = public;

-- SCHEMA

CREATE TABLE categories (category_id SERIAL PRIMARY KEY, name TEXT NOT NULL);

CREATE TABLE customers (
  customer_id SERIAL PRIMARY KEY,
  full_name TEXT NOT NULL,
  email TEXT NOT NULL UNIQUE,
  phone TEXT,
  country TEXT,
  created_at TIMESTAMP DEFAULT NOW()
);

CREATE TABLE products (
  product_id SERIAL PRIMARY KEY,
  name TEXT NOT NULL,
  category_id INT REFERENCES categories(category_id),
  price NUMERIC(10,2) NOT NULL,
  stock INT NOT NULL,
  attributes JSONB,
  created_at TIMESTAMP DEFAULT NOW()
);

CREATE TABLE inventory (
  inventory_id SERIAL PRIMARY KEY,
  product_id INT REFERENCES products(product_id),
  change_amount INT NOT NULL,
  reason TEXT,
  created_at TIMESTAMP DEFAULT NOW()
);

CREATE TABLE orders (
  order_id SERIAL PRIMARY KEY,
  customer_id INT REFERENCES customers(customer_id),
  total_amount NUMERIC(12,2),
  status VARCHAR(20),
  created_at TIMESTAMP DEFAULT NOW()
);

CREATE TABLE order_items (
  order_item_id SERIAL PRIMARY KEY,
  order_id INT REFERENCES orders(order_id) ON DELETE CASCADE,
  product_id INT REFERENCES products(product_id),
  quantity INT,
  price_at_purchase NUMERIC(10,2),
  created_at TIMESTAMP DEFAULT NOW()
);

CREATE TABLE payments (
  payment_id SERIAL PRIMARY KEY,
  order_id INT REFERENCES orders(order_id),
  amount NUMERIC(12,2),
  method VARCHAR(30),
  status VARCHAR(20),
  paid_at TIMESTAMP
);

CREATE TABLE cart (
  cart_id SERIAL PRIMARY KEY,
  customer_id INT REFERENCES customers(customer_id),
  updated_at TIMESTAMP DEFAULT NOW()
);

CREATE TABLE cart_items (
  cart_item_id SERIAL PRIMARY KEY,
  cart_id INT REFERENCES cart(cart_id) ON DELETE CASCADE,
  product_id INT REFERENCES products(product_id),
  quantity INT,
  added_at TIMESTAMP DEFAULT NOW()
);

CREATE TABLE reviews (
  review_id SERIAL PRIMARY KEY,
  product_id INT REFERENCES products(product_id),
  customer_id INT REFERENCES customers(customer_id),
  rating INT CHECK (rating BETWEEN 1 AND 5),
  comment TEXT,
  created_at TIMESTAMP DEFAULT NOW()
);

CREATE TABLE analytics_pageviews (
  pv_id SERIAL PRIMARY KEY,
  customer_id INT REFERENCES customers(customer_id),
  product_id INT REFERENCES products(product_id),
  viewed_at TIMESTAMP DEFAULT NOW()
);

-- Indexes
CREATE INDEX idx_products_category ON products(category_id);
CREATE INDEX idx_customers_email ON customers(email);
CREATE INDEX idx_orders_customer ON orders(customer_id);
CREATE INDEX idx_order_items_order ON order_items(order_id);
CREATE INDEX idx_reviews_product ON reviews(product_id);


